package cn.mop.persistence;
import cn.mop.domain.*;
import cn.mop.domain.assetexport.*;
import cn.mop.domain.assetexport.AssetExportJobRepository.*;
import cn.mop.domain.assetexport.AssetExportJobRepository.Access;
import cn.mop.domain.assetexport.AssetExportPublicationRepository.*;
import cn.mop.domain.assetexport.AssetExportJobState.*;
import com.fasterxml.jackson.databind.*;
import com.zaxxer.hikari.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import java.sql.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import static org.junit.jupiter.api.Assertions.*;

@EnabledIfEnvironmentVariable(named="MOP_RUN_REMOTE_TESTS",matches="true")
class PostgresAssetExportPublicationIntegrationTest {
    static final String TENANT="55000000-0000-4000-8000-000000000001";
    static HikariDataSource pool;static PostgresPlatformRepository platform;static PostgresAssetExportRepository jobs;static ObjectMapper mapper;static String admin;
    @BeforeAll static void connect(){String url=System.getenv("SPRING_DATASOURCE_URL");assertNotNull(url);assertTrue(url.matches("jdbc:postgresql://127\\.0\\.0\\.1:[0-9]+/mop_test"));assertEquals("mop_test_runtime",System.getenv("SPRING_DATASOURCE_USERNAME"));var cfg=new HikariConfig();cfg.setJdbcUrl(url);cfg.setUsername(System.getenv("SPRING_DATASOURCE_USERNAME"));cfg.setPassword(System.getenv("SPRING_DATASOURCE_PASSWORD"));cfg.setMaximumPoolSize(4);pool=new HikariDataSource(cfg);mapper=new ObjectMapper().findAndRegisterModules().setPropertyNamingStrategy(PropertyNamingStrategies.SNAKE_CASE).disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);platform=new PostgresPlatformRepository(pool,mapper);jobs=new PostgresAssetExportRepository(pool,platform);admin=platform.users().stream().filter(u->platform.membership(u.id(),TENANT).filter(m->m.role().equals("padmin")).isPresent()).findFirst().orElseThrow().id();}
    @AfterAll static void close(){if(pool!=null)pool.close();}
    static Access access(){return new Access(admin,TENANT,platform.membership(admin,TENANT).orElseThrow().permissionVersion(),UUID.randomUUID().toString());}
    static Job accept(){var a=access();return mapper.convertValue(platform.idempotentAuthorized(admin,TENANT,"POST /integration/export-publication-prepare",UUID.randomUUID().toString(),"a".repeat(64),a.permissionVersion(),()->jobs.authorizeAcceptance(a),()->jobs.accept(a,new Filters(null,null,null,"MOP-FAKE-PUBLICATION"))),Job.class);}
    record Prepared(Job job,AssetExportPreparedFile file,Claim claim){}
    static Prepared prepare(boolean expire)throws Exception{var j=accept();var c=jobs.claim(j.id(),"publication-integration-prepare",Duration.ofSeconds(expire?3:30)).orElseThrow();var w=jobs.loadWork(c);var f=AssetExportPreparedFile.create(w.claim().command(),"b".repeat(64),1,w.databaseNow(),"MOP-FAKE-PG-PUBLICATION".getBytes(java.nio.charset.StandardCharsets.UTF_8));jobs.prepare(c,f);if(expire)try(var db=pool.getConnection();var s=db.prepareStatement("SELECT pg_sleep(GREATEST(0,EXTRACT(EPOCH FROM (?::timestamptz-clock_timestamp())))+0.02)")){s.setObject(1,c.leaseUntil().atOffset(ZoneOffset.UTC));s.execute();}return new Prepared(jobs.get(access(),j.id()),f,c);}
    static Publication publish(Access a,Prepared p,String key,VerifiedWriter writer){String route="POST /integration/export-publications/"+p.job().id();return mapper.convertValue(platform.idempotentAuthorized(a.actorId(),a.tenantId(),route,key,p.file().encoding().fileSha256(),a.permissionVersion(),()->jobs.authorizePublication(a,p.job().id()),()->jobs.publish(a,p.job().id(),p.job().version(),p.file().encoding().fileSha256(),writer)),Publication.class);}
    @Test void publicationIsExplicitAuditedAndReplayDoesNotStoreTwice()throws Exception{var p=prepare(true);AtomicInteger calls=new AtomicInteger();String key=UUID.randomUUID().toString();var a=access();var first=publish(a,p,key,(object,file)->{calls.incrementAndGet();assertEquals("asset-exports/"+TENANT+"/"+p.job().id(),object);assertTrue(file.sameContent(p.file()));});assertTrue(first.published());assertEquals(p.job().version()+2,first.job().version());assertEquals(2,jobs.progress(a,p.job().id()).attempts());assertEquals(first,publish(a,p,key,(object,file)->fail("Replay must not upload")));assertEquals(1,calls.get());try(var c=pool.getConnection();var s=c.prepareStatement("SELECT count(*) FROM mop_audit WHERE payload->>'resource_id'=? AND payload->>'action'='asset_export.publish'")){s.setString(1,p.job().id());try(var r=s.executeQuery()){assertTrue(r.next());assertEquals(1,r.getInt(1));}}}
    @Test void activePreparationLeaseIsNotStolen()throws Exception{var p=prepare(false);var e=assertThrows(DomainException.class,()->publish(access(),p,UUID.randomUUID().toString(),(k,f)->fail()));assertEquals("EXPORT_PREPARATION_ACTIVE",e.code);assertEquals(p.job(),jobs.get(access(),p.job().id()));}
    @Test void unknownStorageRollsBackWithoutOverwritingPreparedBytesAndSameRequestCanReconcile()throws Exception{var p=prepare(true);String key=UUID.randomUUID().toString();assertEquals(503,assertThrows(DomainException.class,()->publish(access(),p,key,(k,f)->{throw new DomainException(503,"UPSTREAM_UNAVAILABLE","synthetic unknown storage outcome");})).status);assertEquals(p.job(),jobs.get(access(),p.job().id()));assertEquals(1,jobs.progress(access(),p.job().id()).attempts());assertTrue(publish(access(),p,key,(k,f)->assertTrue(f.sameContent(p.file()))).published());}
    @Test void staleVersionAndDifferentFileNeverReachStore()throws Exception{var p=prepare(true);var changed=new Prepared(new Job(p.job().id(),TENANT,admin,p.job().permissionVersion(),"padmin",p.job().inputSha256(),p.job().filters(),p.job().state(),p.job().version()+1,p.job().createdAt(),p.job().updatedAt()),p.file(),p.claim());assertEquals(409,assertThrows(DomainException.class,()->publish(access(),changed,UUID.randomUUID().toString(),(k,f)->fail())).status);var a=access();assertEquals(409,assertThrows(DomainException.class,()->platform.idempotentAuthorized(admin,TENANT,"POST /integration/export-wrong-file",UUID.randomUUID().toString(),"c".repeat(64),a.permissionVersion(),()->jobs.authorizePublication(a,p.job().id()),()->jobs.publish(a,p.job().id(),p.job().version(),"c".repeat(64),(k,f)->fail()))).status);}
    @Test void queuedJobsCannotBePublished()throws Exception{var j=accept();assertFalse(jobs.publication(access(),j.id()).published());var a=access();assertEquals(409,assertThrows(DomainException.class,()->platform.idempotentAuthorized(admin,TENANT,"POST /integration/export-unprepared",UUID.randomUUID().toString(),"a".repeat(64),a.permissionVersion(),()->jobs.authorizePublication(a,j.id()),()->jobs.publish(a,j.id(),1,"a".repeat(64),(k,f)->fail()))).status);}
    @Test void otherOwnerTenantAndStaleMembershipCannotAccessPublication()throws Exception{var p=prepare(true);var a=access();publish(a,p,UUID.randomUUID().toString(),(k,f)->{});String other=platform.users().stream().filter(u->platform.membership(u.id(),TENANT).filter(m->m.role().equals("msp")).isPresent()).findFirst().orElseThrow().id();var otherAccess=new Access(other,TENANT,platform.membership(other,TENANT).orElseThrow().permissionVersion(),"other-owner");assertEquals(404,assertThrows(DomainException.class,()->jobs.publication(otherAccess,p.job().id())).status);String t="55000000-0000-4000-8000-000000000002";var m=platform.membership(admin,t).orElseThrow();assertEquals(404,assertThrows(DomainException.class,()->jobs.publication(new Access(admin,t,m.permissionVersion(),"other-tenant"),p.job().id())).status);assertEquals(401,assertThrows(DomainException.class,()->jobs.publication(new Access(admin,TENANT,a.permissionVersion()+1,"stale"),p.job().id())).status);}
    @Test void concurrentSameKeyCommitsOneStoreAndOneOriginalReceipt()throws Exception{var p=prepare(true);String key=UUID.randomUUID().toString();var a=access();var start=new CountDownLatch(1);AtomicInteger calls=new AtomicInteger();var executor=Executors.newFixedThreadPool(2);try{Callable<Publication> action=()->{start.await();return publish(a,p,key,(k,f)->calls.incrementAndGet());};var x=executor.submit(action);var y=executor.submit(action);start.countDown();assertEquals(x.get(20,TimeUnit.SECONDS),y.get(20,TimeUnit.SECONDS));assertEquals(1,calls.get());}finally{executor.shutdownNow();}}
    @Test void commandScopeIsRequiredAndReadIsStandalone()throws Exception{var p=prepare(true);assertThrows(IllegalStateException.class,()->jobs.publish(access(),p.job().id(),p.job().version(),p.file().encoding().fileSha256(),(k,f)->fail()));assertThrows(IllegalStateException.class,()->jobs.publicationInCommand(access(),p.job().id()));}
}
